function action(error:string){if(error){toast(error);actionHistory.unshift({time:world.time,text:error});actionHistory.splice(50);}evaluate(world);renderUI(true);}
function setTool(tool:View['tool'],build:Kind|null=null){view.tool=tool;view.build=build;objectSelection=null;view.objectSelection=null;view.editing=null;if(build){$('build-requirements').innerHTML=requirements(build);canvas.focus();if(!view.cursor){const c=renderer.world(renderer.width/2,renderer.height/2);view.cursor={x:Math.max(0,Math.min(WIDTH-1,Math.round(c.x))),y:Math.max(0,Math.min(HEIGHT-1,Math.round(c.y)))};}}view.pending=null;view.waypoints=[];renderUI(true);}
