/** Modal helpers: record the opener, own the modal pause reason, and return focus on close. */
function openDialog(dialog:HTMLDialogElement){dialog.dataset.opener=(document.activeElement as HTMLElement)?.id||'';pause.set(PAUSE.modal,true);if(!dialog.open)dialog.showModal();}
function closeDialog(dialog:HTMLDialogElement){if(dialog.open)dialog.close();pause.set(PAUSE.modal,!!document.querySelector('dialog[open]'));const opener=dialog.dataset.opener,el=opener?document.getElementById(opener):null;if(el instanceof HTMLElement)el.focus();}
for(const dialog of Array.from(document.querySelectorAll<HTMLDialogElement>('dialog')))dialog.addEventListener('close',()=>pause.set(PAUSE.modal,!!document.querySelector('dialog[open]')));
function openOperations(){$('operations-body').innerHTML=renderOperations(world);openDialog($<HTMLDialogElement>('operations'));}
