function zoom(factor:number,sx=renderer.width/2,sy=renderer.height/2){const before=renderer.world(sx,sy);view.zoom=Math.max(.3,Math.min(3.5,view.zoom*factor));renderer.resize();view.panX=sx-before.x*renderer.scale;view.panY=sy-before.y*renderer.scale;cameraMoved=true;}
$('zoom-in').onclick=()=>zoom(1.25);$('zoom-out').onclick=()=>zoom(.8);$('fit-map').onclick=()=>{view.zoom=1;renderer.resize();view.zoom=Math.min(renderer.width/64,renderer.height/36)/renderer.scale*.95;renderer.resize();minimap.center(32,18);cameraMoved=true;};
let category='All';
$('build-categories').innerHTML=categories.map(c=>`<button role="tab" aria-selected="${c===category}" data-category="${c}">${c}</button>`).join('');
/** Combined category AND query filtering shared by the catalog popover and the strip. */
function applyFilter(){const query=$<HTMLInputElement>('build-search').value.toLowerCase().trim();palette.querySelectorAll<HTMLButtonElement>('[data-build]').forEach(b=>{const kind=b.dataset.build as Kind;const matchesCategory=category==='All'||catalog[kind].category===category;const matchesQuery=!query||DEFS[kind].name.toLowerCase().includes(query)||kind.includes(query);b.hidden=!(matchesCategory&&matchesQuery);});}
function selectCategory(c:string){category=c;$('build-categories').querySelectorAll<HTMLButtonElement>('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===c);b.setAttribute('aria-selected',String(b.dataset.category===c));});applyFilter();}
$('build-categories').onclick=e=>{const c=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-category]')?.dataset.category;if(c)selectCategory(c);};
$('build-categories').onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();e.stopPropagation();const i=categories.indexOf(category as typeof categories[number]),c=categories[(i+(e.key==='ArrowRight'?1:categories.length-1))%categories.length];selectCategory(c);$('build-categories').querySelector<HTMLButtonElement>(`[data-category="${c}"]`)!.focus();};
for(const type of ['pointerover','focusin'])palette.addEventListener(type,e=>{const k=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-build]')?.dataset.build as Kind|undefined;if(k)$('build-requirements').innerHTML=requirements(k);});
selectCategory('All');
$('build-search').oninput=applyFilter;
function openCatalog(){const p=$('catalog-popover');if(!p.hidden)return;p.hidden=false;$('catalog-toggle').setAttribute('aria-expanded','true');$<HTMLInputElement>('build-search').focus();}
function closeCatalog(){const p=$('catalog-popover');if(p.hidden)return;p.hidden=true;$('catalog-toggle').setAttribute('aria-expanded','false');}
$('catalog-toggle').onclick=()=>{if($('catalog-popover').hidden)openCatalog();else closeCatalog();};
$('catalog-close').onclick=()=>closeCatalog();
$('minimap-toggle').onclick=()=>{const w=$('minimap-wrap'),show=w.hidden;w.hidden=!show;$('minimap-toggle').hidden=show;$('minimap-toggle').setAttribute('aria-expanded',String(show));if(show)minimap.draw(world);};
$('minimap-close').onclick=()=>{$('minimap-wrap').hidden=true;$('minimap-toggle').hidden=false;$('minimap-toggle').setAttribute('aria-expanded','false');$('minimap-toggle').focus();};
$('issues').onclick=()=>{$('diagnostics-panel').hidden=!$('diagnostics-panel').hidden;};$('close-issues').onclick=()=>{$('diagnostics-panel').hidden=true;};
$('close-inspector').onclick=()=>closeDrawer();
$('objective-toggle').onclick=()=>{const show=$('objective-panel').hidden;$('objective-panel').hidden=!show;$('objective-toggle').setAttribute('aria-expanded',String(show));};
function focusObject(id:string){setTool('select');const e=entity(world,id),d=world.deposits.find(d=>d.id===id),c=world.ecology.creatures.find(c=>c.id===id);view.selected=e?.id??null;objectSelection=e?null:id;view.objectSelection=objectSelection;const p=e??d??c??frontierTarget(world);if(!p)return;minimap.center(p.x+('w' in p?p.w/2:0),p.y+('h' in p?p.h/2:0));renderUI(true);revealInspector();}
const escapeHTML=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
let issues:Issue[]=[];let issueStates=new Map<string,string>();
const trend:{t:number;target:number;demand:number;heat:number;leaked:number}[]=[];let lastTrend=-1;
function sampleTrend(){if(world.time-lastTrend<1)return;lastTrend=world.time;const s=world.stats;trend.push({t:world.time,target:s.targetPower,demand:s.demand,heat:s.heat,leaked:s.leaked});if(trend.length>120)trend.shift();}
function renderTrends(){const summary=$('trend-summary'),chart=$('trend-chart');if(trend.length<2){summary.textContent='Collecting telemetry…';chart.innerHTML='';return;}const series=(k:'target'|'heat'|'demand')=>trend.map(s=>s[k]);const target=series('target'),min=Math.min(...target),max=Math.max(...target),avg=target.reduce((a,b)=>a+b,0)/target.length,tHi=Math.max(40,max*1.1),hHi=Math.max(1,...series('heat'));const path=(vals:number[],hi:number)=>vals.map((v,i)=>`${i?'L':'M'}${(i/(vals.length-1))*316+2},${57-Math.min(1,Math.max(0,v/hi))*52}`).join(' ');chart.innerHTML=`<path d="${path(target,tHi)}" fill="none" stroke="#8ae2cc" stroke-width="2"/><path d="${path(series('heat'),hHi)}" fill="none" stroke="#e4a06f" stroke-width="1.5" stroke-dasharray="3 2"/>`;summary.textContent=`Target ${fmt(min)}–${fmt(max)} · avg ${fmt(avg)} field units · ${trend.length} samples · heat peak ${fmt(hHi)}`;}
function trendReport(){return [`PHIELDWORKS report @ ${world.time.toFixed(1)} s`,...issues.map(i=>`${i.severity.toUpperCase()} ${i.title}: ${i.remedy}`),...[...actionHistory,...world.events].slice(0,20).map(e=>`${e.time.toFixed(1)} s ${e.text}`)].join('\n');}
$('active-issues').onclick=e=>{const id=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-focus]')?.dataset.focus;if(id)focusObject(id);};
function renderDiagnostics(){issues=diagnose(world);const current=new Map(issues.map(i=>[i.id,i.title]));for(const i of issues)if(!issueStates.has(i.id)&&i.severity!=='info')actionHistory.unshift({time:world.time,text:`Detected: ${i.title} (${i.object??'network'}). ${i.remedy}`});for(const [id,title] of issueStates)if(!current.has(id))actionHistory.unshift({time:world.time,text:`Resolved: ${title}`});issueStates=current;actionHistory.splice(50);const issueCount=issues.filter(i=>i.severity!=='info').length;$('issues-badge').hidden=!issueCount;$('issues-badge').textContent=String(issueCount);$('issues').setAttribute('aria-label',issueCount?`Diagnostics · ${issueCount} issues`:'Diagnostics');if($('diagnostics-panel').hidden)return;const filter=$<HTMLSelectElement>('issue-filter').value,visible=issues.filter(i=>filter==='all'||i.severity===filter);const html=visible.map(i=>`<article class="issue ${i.severity}"><div class="issue-head"><b>${escapeHTML(i.title)}</b><small>${i.severity.toUpperCase()}${i.object?' · '+escapeHTML(i.object):''}</small>${i.object?`<button data-focus="${escapeHTML(i.object)}" aria-label="Locate &amp; inspect">Locate</button>`:''}</div><details class="issue-detail"><summary>Details</summary><p>${escapeHTML(i.remedy)}</p></details></article>`).join('')||'<p>No active issues at this severity.</p>';if($('active-issues').innerHTML!==html)$('active-issues').innerHTML=html;$('issue-history').innerHTML=[...actionHistory,...world.events].sort((a,b)=>b.time-a.time).slice(0,30).map(e=>`<p><time>${e.time.toFixed(1)} s</time> ${escapeHTML(e.text)}</p>`).join('');renderTrends();}
$('copy-report').onclick=()=>{const report=trendReport();navigator.clipboard?.writeText(report).then(()=>toast('Diagnostic report copied')).catch(()=>{actionHistory.unshift({time:world.time,text:'Clipboard unavailable; report kept in history'});toast('Clipboard unavailable');renderUI(true);});};

$('pause').onclick=()=>{pause.set(PAUSE.user,!pause.has(PAUSE.user));renderUI();};$('speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;renderUI();};
const storageKey='fieldworks.save.v1';
function saveGame(){try{localStorage.setItem(storageKey,serialize(world));toast('Expedition saved locally');}catch{toast('Save failed: browser storage is unavailable or full');}}
function loadGame(){try{const raw=localStorage.getItem(storageKey);if(!raw){toast('No saved expedition yet');return;}world=deserialize(raw);objectSelection=null;view.objectSelection=null;actionHistory.length=0;issueStates.clear();trend.length=0;lastTrend=-1;view.selected=null;selectedCache='';setTool('select');toast('Save restored. Recommission to verify the installation.');}catch(err){toast(`Load failed: ${err instanceof Error?err.message:'invalid save'}`);}}
function requestNewGame(){openDialog($<HTMLDialogElement>('confirm-reset'));}
function openManual(){openDialog($<HTMLDialogElement>('manual'));}
$('menu').onclick=()=>openDialog($<HTMLDialogElement>('session'));
$('cancel-new').onclick=()=>closeDialog($<HTMLDialogElement>('confirm-reset'));$('confirm-new').onclick=()=>{world=createWorld();objectSelection=null;view.objectSelection=null;actionHistory.length=0;issueStates.clear();trend.length=0;lastTrend=-1;tutorial.replay();view.selected=null;selectedCache='';pause.clear();speed=1;home();setTool('select');closeDialog($<HTMLDialogElement>('confirm-reset'));toast('New expedition started');};
