$('close-session').onclick=()=>closeDialog($<HTMLDialogElement>('session'));
$('session-resume').onclick=()=>closeDialog($<HTMLDialogElement>('session'));
$('session-operations').onclick=()=>{closeDialog($<HTMLDialogElement>('session'));openOperations();};
$('session-technology').onclick=()=>{closeDialog($<HTMLDialogElement>('session'));$('technology').click();};
