let previous=performance.now(),accumulator=0,lastUI=0;
function frame(now:number){const elapsed=Math.min(.2,(now-previous)/1000);previous=now;if(!pause.paused&&!document.hidden&&!document.querySelector('dialog[open]')){accumulator+=elapsed*speed;while(accumulator>=DT){step(world);accumulator-=DT;}for(const id of continuousTargets)if(!world.jobs.some(j=>j.target===id&&j.stage!=='complete'))reserveProcess(world,id);}else accumulator=0;renderer.draw(world);minimap.draw(world);if(now-lastUI>150){renderUI();lastUI=now;}if(now>toastUntil)$('toast').classList.remove('visible');requestAnimationFrame(frame);}
async function start(){try{await loadSprites();renderer.fit();renderUI(true);requestAnimationFrame(frame);}catch(err){$('runtime-status').textContent='ASSET LOAD FAILED';toast(String(err));}}
